package io.github.diodeme.ji.security.secret;

import java.util.Arrays;
import java.util.Objects;
import java.util.function.Function;

/** A 256-bit master key that is never exposed as a serializable DTO. */
public final class MasterKey implements AutoCloseable {
    public static final int BYTES = 32;

    private final String keyId;
    private byte[] keyBytes;

    public MasterKey(String keyId, byte[] keyBytes) {
        if (keyId == null || keyId.isBlank()) throw new IllegalArgumentException("keyId must not be blank");
        Objects.requireNonNull(keyBytes, "keyBytes");
        if (keyBytes.length != BYTES) throw new IllegalArgumentException("master key must be 256 bits");
        this.keyId = keyId;
        this.keyBytes = keyBytes.clone();
    }

    public String keyId() {
        return keyId;
    }

    public synchronized <T> T useBytes(Function<byte[], T> action) {
        Objects.requireNonNull(action, "action");
        ensureOpen();
        byte[] copy = keyBytes.clone();
        try {
            return action.apply(copy);
        } finally {
            Arrays.fill(copy, (byte) 0);
        }
    }

    @Override
    public synchronized void close() {
        if (keyBytes != null) {
            Arrays.fill(keyBytes, (byte) 0);
            keyBytes = null;
        }
    }

    @Override
    public String toString() {
        return "MasterKey[keyId=" + keyId + ", material=REDACTED]";
    }

    private void ensureOpen() {
        if (keyBytes == null) throw new IllegalStateException("master key is closed");
    }
}
